3	// Wraps a route handler so every thrown error becomes the SPEC error body (D2), never a stack trace.
4	export function route<C>(handler: (req: Request, ctx: C) => Promise<Response>): (req: Request, ctx: C) => Promise<Response> {
5	  return async (req, ctx) => {
6	    try {
7	      return await handler(req, ctx)
8	    } catch (e) {
9	      return toErrorResponse(e)
10	    }
11	  }
12	}
